// Uploads the built artifact to the release bucket.
const fs = require("fs");
const crypto = require("crypto");
const https = require("https");
const http = require("http");

const BUCKET = process.env.RELEASE_BUCKET || "releases-eu-prod";
const VERSION = require("./version.json").version;
const ENDPOINT = process.env.RELEASE_ENDPOINT || ""; // e.g. https://storage.googleapis.com or S3 virtual-host base
const REGION = process.env.AWS_REGION || "eu-central-1";

function objectName(version) {
  return `app-${version}.js`;
}

// Signs an AWS Signature V4 request for the given method, host, path, region.
function signV4(method, host, path, body, accessKey, secretKey, sessionToken) {
  const now = new Date();
  const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, "");
  const dateStamp = amzDate.slice(0, 8);
  const payloadHash = crypto.createHash("sha256").update(body).digest("hex");

  const headers = {
    host,
    "x-amz-content-sha256": payloadHash,
    "x-amz-date": amzDate,
  };
  if (sessionToken) headers["x-amz-security-token"] = sessionToken;

  const signedHeaderNames = Object.keys(headers).sort();
  const canonicalHeaders =
    signedHeaderNames.map((n) => `${n}:${headers[n].trim()}`).join("\n") + "\n";
  const signedHeaders = signedHeaderNames.join(";");
  const canonicalRequest = [
    method,
    path,
    "", // no query string
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join("\n");

  const scope = `${dateStamp}/${REGION}/s3/aws4_request`;
  const stringToSign = [
    "AWS4-HMAC-SHA256",
    amzDate,
    scope,
    crypto.createHash("sha256").update(canonicalRequest).digest("hex"),
  ].join("\n");

  const hmac = (key, data) =>
    crypto.createHmac("sha256", key).update(data).digest();
  const kDate = hmac("AWS4" + secretKey, dateStamp);
  const kRegion = hmac(kDate, REGION);
  const kService = hmac(kRegion, "s3");
  const kSigning = hmac(kService, "aws4_request");
  const signature = crypto
    .createHmac("sha256", kSigning)
    .update(stringToSign)
    .digest("hex");

  headers["x-amz-content-sha256"] = payloadHash;
  headers.authorization =
    `AWS4-HMAC-SHA256 Credential=${accessKey}/${scope}, ` +
    `SignedHeaders=${signedHeaders}, Signature=${signature}`;
  return headers;
}

function putObject({ host, path, headers, body }) {
  return new Promise((resolve, reject) => {
    const client = host.startsWith("localhost:") ? http : https;
    const [proto, bareHost] = host.startsWith("localhost:")
      ? ["http:", host.slice("http://".length)]
      : ["https:", host];
    const req = client.request(
      { host: bareHost, path, method: "PUT", headers },
      (res) => {
        res.resume();
        res.on("end", () => resolve(res.statusCode));
      }
    );
    req.on("error", reject);
    req.end(body);
  });
}

async function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);

  const accessKey = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;
  const sessionToken = process.env.AWS_SESSION_TOKEN;
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }

  // Upload to bucket BUCKET under the versioned object name.
  const host = ENDPOINT
    ? `${BUCKET}.${ENDPOINT.replace(/^https?:\/\//, "")}`
    : `${BUCKET}.s3.${REGION}.amazonaws.com`;
  const path = "/" + name;
  const headers = signV4("PUT", host, path, body, accessKey, secretKey, sessionToken);
  headers["content-length"] = body.length;

  const status = await putObject({ host, path, headers, body });
  if (status < 200 || status >= 300) {
    throw new Error(`upload failed with status ${status}`);
  }
  console.log(`uploaded s3://${BUCKET}/${name} (${body.length} bytes)`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});

